import {POOL,symbolCount} from './engine.js?v=15';
export const ATOMIC='H He Li Be B C N O F Ne Na Mg Al Si P S Cl Ar K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe Cs Ba La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn Fr Ra Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm Md No Lr Rf Db Sg Bh Hs Mt Ds Rg Cn Nh Fl Mc Lv Ts Og'.split(' ');
export const ORDER=[...POOL,...ATOMIC.filter(s=>!POOL.includes(s))];
export const NAMES={Na:'Натрій',Cl:'Хлор',Fe:'Залізо',O:'Кисень',C:'Вуглець',H:'Водень',Au:'Золото',Li:'Літій',He:'Гелій',Be:'Берилій',B:'Бор',N:'Азот',F:'Фтор',Ne:'Неон',Mg:'Магній',Al:'Алюміній',Si:'Кремній',P:'Фосфор',S:'Сірка'};
export const tint=s=>`hsl(${(ORDER.indexOf(s)*137.508+28)%360} 76% 58%)`;
export const ARTIFACTS=[{id:'sun',name:'Сонячне ядро',icon:'☀'},{id:'ice',name:'Серце полюса',icon:'❄'},{id:'prism',name:'Призма світанку',icon:'◈'},{id:'orbit',name:'Кільце орбіти',icon:'◎'},{id:'nova',name:'Осколок наднової',icon:'✺'},{id:'seed',name:'Зерно безмежності',icon:'❖'}];
const types=['blast','freeze','gold','crystal','artifact'];
const base=[['Na','Cl','blast','Спалах наднової'],['Cl','Fe','freeze','Полярне серце'],['Na','Fe','gold','Золотий дощ']];
export const RECIPES=[...base.map((r,i)=>({id:`r${i}`,a:r[0],b:r[1],type:r[2],name:r[3]})),...ORDER.slice(3).map((s,i)=>({id:`r${i+3}`,a:s,b:ORDER[i%3],type:types[(i+3)%5],name:['Зоряний імпульс','Крижаний резонанс','Сонячний осад','Кристалічне ехо','Реліктова іскра'][(i+3)%5]}))];
export const CHEMISTRY={
 'Na+Cl':{equation:'2Na + Cl₂ → 2NaCl',product:'хлорид натрію',note:'Окисно-відновна реакція з виділенням енергії; показано сумарне рівняння.'},
 'Cl+Fe':{equation:'2Fe + 3Cl₂ → 2FeCl₃',product:'хлорид заліза(III)',note:'Екзотермічна реакція заліза з хлором.'},
 'H+O':{equation:'2H₂ + O₂ → 2H₂O',product:'вода',note:'Реакція горіння водню; потребує запалювання.'},
 'C+O':{equation:'C + O₂ → CO₂',product:'вуглекислий газ',note:'Повне горіння вуглецю за наявності кисню.'},
 'Fe+O':{equation:'4Fe + 3O₂ → 2Fe₂O₃',product:'оксид заліза(III)',note:'Окиснення заліза киснем.'}
};
export const chemistryFor=(a,b)=>CHEMISTRY[[a,b].sort().join('+')]||null;
export const UPGRADES=[{id:'collector',name:'Збирач осаду',icon:'✦',description:'+5 монет за кожну реакцію на ступінь',base:120},{id:'reactor',name:'Реактор',icon:'◉',description:'+1 реакція на рівень на ступінь',base:180},{id:'spectrometer',name:'Спектрометр',icon:'◈',description:'+1 кристал за кристалічну реакцію на ступінь',base:160}];
export const utcDay=(date=new Date())=>date.toISOString().slice(0,10);
const int=(x,d=0)=>Number.isFinite(x)?Math.max(0,Math.floor(x)):d;
export const CITY_BRANCHES=[{id:'medicine',name:'Медицина',icon:'✚',description:'Лабораторії, вакцини та чиста вода',elements:['O','Cl','Na','C']},{id:'industry',name:'Промисловість',icon:'⚙',description:'Метали, сплави та енергія',elements:['Fe','C','Si','Al']},{id:'technology',name:'Технології',icon:'⌬',description:'Провідники, батареї та оптика',elements:['Li','Si','B','Ne']}];
export function normalizeMeta(raw,level=1){const r=raw&&typeof raw==='object'?raw:{};return{version:3,frozen:!!r.frozen,crystals:int(r.crystals),reactions:int(r.reactions),wins:int(r.wins,Math.max(0,level-1)),artifacts:Array.isArray(r.artifacts)?r.artifacts.filter(s=>ARTIFACTS.some(a=>a.id===s)):[],upgrades:Object.fromEntries(UPGRADES.map(u=>[u.id,Math.min(5,int(r.upgrades?.[u.id]))])),city:Object.fromEntries(CITY_BRANCHES.map(b=>[b.id,Math.min(5,int(r.city?.[b.id]))])),reactionLevel:int(r.reactionLevel),reactionClaims:Array.isArray(r.reactionClaims)?r.reactionClaims.filter(id=>RECIPES.some(a=>a.id===id)):[],boardClaims:Array.isArray(r.boardClaims)?r.boardClaims.filter(id=>RECIPES.some(a=>a.id===id)):[],daily:{day:typeof r.daily?.day==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.daily.day)?r.daily.day:'',wins:int(r.daily?.wins),reactions:int(r.daily?.reactions),clean:int(r.daily?.clean),claimed:Array.isArray(r.daily?.claimed)?r.daily.claimed.filter(id=>['wins','reactions','clean'].includes(id)):[]},secrets:Array.isArray(r.secrets)?r.secrets.filter(id=>['first','collector','explorer'].includes(id)):[]};}
export function cityUpgrade(core,meta,id){const branch=CITY_BRANCHES.find(b=>b.id===id),level=meta.city[id]||0;if(!branch||level>=5)return false;const cost=180+level*140;if(core.gold<cost)return false;core.gold-=cost;meta.city[id]=level+1;return true;}
export const cityImpact=(symbol,meta)=>CITY_BRANCHES.filter(b=>b.elements.includes(symbol)).map(b=>b.id);
export function rollDay(meta,today=utcDay()){if(today>meta.daily.day)meta.daily={day:today,wins:0,reactions:0,clean:0,claimed:[]};return meta.daily;}
export function dailyTasks(meta){const odd=Number(meta.daily.day.replaceAll('-',''))%2;return[{id:'wins',title:odd?'Два відкриті горизонти':'Перший експеримент',target:odd?2:1,gold:90,crystals:2},{id:'reactions',title:'Запусти дві реакції',target:2,gold:70,crystals:3},{id:'clean',title:'Пройди рівень без допомоги',target:1,gold:120,crystals:2}];}
export function claimDaily(core,meta,id,today=utcDay()){rollDay(meta,today);const task=dailyTasks(meta).find(t=>t.id===id);if(!task||meta.daily.claimed.includes(id)||meta.daily[id]<task.target)return false;meta.daily.claimed.push(id);core.gold+=task.gold;meta.crystals+=task.crystals;return true;}
export function resetReactionLevel(meta,level){if(meta.reactionLevel!==level){meta.reactionLevel=level;meta.reactionClaims=[];meta.boardClaims=[];meta.frozen=false;}}
export function reactionReward(recipe,meta){return{gold:(recipe.type==='gold'?45:15)+5*meta.upgrades.collector,crystals:recipe.type==='crystal'?3+meta.upgrades.spectrometer:recipe.type==='freeze'?2:0,artifact:recipe.type==='artifact'?ARTIFACTS[(Number(recipe.id.slice(1))%ARTIFACTS.length)].id:null};}
export function runReaction(core,meta,id,today=utcDay()){rollDay(meta,today);resetReactionLevel(meta,core.level);const recipe=RECIPES.find(r=>r.id===id);if(meta.frozen||!recipe||![recipe.a,recipe.b].every(s=>core.discovered.includes(s))||meta.reactionClaims.includes(id)||meta.reactionClaims.length>=3+meta.upgrades.reactor)return null;const reward=reactionReward(recipe,meta);meta.reactionClaims.push(id);meta.frozen=recipe.type==='freeze';meta.reactions++;meta.daily.reactions++;core.gold+=reward.gold;meta.crystals+=reward.crystals;if(reward.artifact&&!meta.artifacts.includes(reward.artifact))meta.artifacts.push(reward.artifact);if(meta.reactions%5===0){const artifact=ARTIFACTS.find(a=>!meta.artifacts.includes(a.id));if(artifact){meta.artifacts.push(artifact.id);reward.artifact=artifact.id;}}return{recipe,reward};}
export function reactionForPair(a,b){return RECIPES.find(recipe=>(recipe.a===a&&recipe.b===b)||(recipe.a===b&&recipe.b===a))||null;}
export function runBoardReaction(core,meta,a,b,today=utcDay()){rollDay(meta,today);resetReactionLevel(meta,core.level);const recipe=reactionForPair(a,b);if(!recipe||meta.boardClaims.includes(recipe.id)||![recipe.a,recipe.b].every(s=>core.discovered.includes(s)))return null;const reward=reactionReward(recipe,meta);meta.boardClaims.push(recipe.id);meta.reactions++;meta.daily.reactions++;core.gold+=reward.gold;meta.crystals+=reward.crystals;if(reward.artifact&&!meta.artifacts.includes(reward.artifact))meta.artifacts.push(reward.artifact);return{recipe,reward};}
export function researchQuest(core,meta){const s=ORDER.find(s=>!core.discovered.includes(s));if(!s)return null;const index=ORDER.indexOf(s);const requiredLevel=Math.max(2,(index-2)*2),requiredReactions=index-2;return{symbol:s,requiredLevel,requiredReactions,ready:core.level>=requiredLevel&&meta.reactions>=requiredReactions};}
export function claimResearch(core,meta){const q=researchQuest(core,meta);if(!q?.ready)return null;core.discovered.push(q.symbol);meta.crystals+=3;return q.symbol;}
export function unlockNextElement(core,meta){const symbol=ORDER.find(s=>!core.discovered.includes(s));if(!symbol)return null;core.discovered.push(symbol);meta.crystals+=3;return symbol;}
export function buyUpgrade(core,meta,id){const u=UPGRADES.find(u=>u.id===id);if(!u||meta.upgrades[id]>=5)return false;const cost=u.base*(meta.upgrades[id]+1);if(core.gold<cost)return false;core.gold-=cost;meta.upgrades[id]++;return true;}
export function claimSecret(core,meta,id){const ready={first:meta.reactions>=1,collector:meta.artifacts.length>=3,explorer:core.discovered.length>=10};if(!ready[id]||meta.secrets.includes(id))return false;meta.secrets.push(id);core.gold+=100;meta.crystals+=5;return true;}
export function activeSymbols(core){const count=Math.min(core.discovered.length,symbolCount(core.level));const arr=[core.discovered.at(-1)];for(let i=0;arr.length<count;i++){const s=core.discovered[(core.level-1+i)%core.discovered.length];if(!arr.includes(s))arr.push(s);}return arr;}
export function tablePositions(){const positions=[];const add=(symbols,row,start)=>symbols.split(' ').forEach((s,i)=>positions.push({s,row,col:start+i}));add('H',1,1);add('He',1,18);add('Li Be',2,1);add('B C N O F Ne',2,13);add('Na Mg',3,1);add('Al Si P S Cl Ar',3,13);add('K Ca Sc Ti V Cr Mn Fe Co Ni Cu Zn Ga Ge As Se Br Kr',4,1);add('Rb Sr Y Zr Nb Mo Tc Ru Rh Pd Ag Cd In Sn Sb Te I Xe',5,1);add('Cs Ba',6,1);add('Hf Ta W Re Os Ir Pt Au Hg Tl Pb Bi Po At Rn',6,4);add('Fr Ra',7,1);add('Rf Db Sg Bh Hs Mt Ds Rg Cn Nh Fl Mc Lv Ts Og',7,4);add('La Ce Pr Nd Pm Sm Eu Gd Tb Dy Ho Er Tm Yb Lu',9,3);add('Ac Th Pa U Np Pu Am Cm Bk Cf Es Fm Md No Lr',10,3);return positions;}
